package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.mapper.SourceExactMapper;
import java.util.*;

/** Typed-family TEXT values come from a genuine exact manifest and approved context original bytes. */
final class TaskStrictFieldTextEvidence {
    private final SourceExactMapper rows;private final SourceExactSchema exact;private final StrictComparisonCodec codec;
    TaskStrictFieldTextEvidence(SourceExactMapper rows,SourceExactSchema exact,StrictComparisonCodec codec){this.rows=rows;this.exact=exact;this.codec=codec;}
    Verified require(EnterpriseAccess.Admission a,String project,TaskStrictFieldContextService.Verified context,StrictFieldComparisonProtocol.SourceExactReference reference)throws Exception{
        context.requireApproved();Objects.requireNonNull(reference);var evidence=context.evidence();var args=new HashMap<String,Object>();args.put("sourceVersion",evidence.sourceVersion());args.put("fieldRevision",reference.fieldRevision());args.put("projectId",project);args.put("userId",a.actorId());args.put("fieldLimit",10001);
        var r=one(rows.revision(args));var manifest=exact.parse(str(r,"manifest"));exact.require("Manifest",manifest);var input=exact.storedInput(manifest.required("request"));var sourceProof=context.sourceProof();if(!sourceProof.source().originalSha256().equals(manifest.required("original_sha256").asText())||!sourceProof.selection().bindingRevision().equals(input.binding_revision())||!sourceProof.selection().indexVersion().equals(input.index_version())||!sourceProof.rights().rightsRevision().equals(input.rights_revision()))bad();
        if(!reference.fieldManifestSha256().equals(codec.hash(manifest))||!reference.fieldManifestSha256().equals(str(r,"manifest_sha256"))||!reference.fieldManifestSha256().equals(str(r,"registered_sha256"))||!"SOURCE_EXACT_REVISION".equals(str(r,"entity_kind"))||!project.equals(input.project_id())||!evidence.parseVersion().equals(input.parse_version())||!evidence.approvalRevision().equals(input.approval_revision())||input.fields().size()>10000||reference.ordinal()<0||reference.ordinal()>=input.fields().size())bad();
        var field=input.fields().get(reference.ordinal());exact.checkField(field);var fields=rows.fields(args);if(fields.size()!=input.fields().size()||!codec.tree(field).equals(exact.parse(str(fields.get(reference.ordinal()),"field_manifest")))||!reference.fieldKind().equals(field.field_kind())||!evidence.chunkId().equals(field.chunk_id())||!evidence.quoteHash().equals(field.quote_hash())||!field.raw_value().equals(TaskStrictFieldTypedProtocol.span(context.originalChunk(),new StrictComparisonProtocol.Span(field.start_codepoint(),field.end_codepoint()))))bad();
        var value=new ArtifactProtocol.FieldValue(ArtifactProtocol.ValueKind.TEXT,field.raw_value(),null,null,null,List.of(),null);var source=new StrictFieldComparisonProtocol.SourceIdentity("SOURCE_EXACT_REVISION",evidence,reference,null);var provenance=new StrictFieldComparisonProtocol.Provenance(source,List.of(context.revisionId()),field.start_codepoint(),field.end_codepoint(),WireValues.sha256(field.raw_value().getBytes(java.nio.charset.StandardCharsets.UTF_8)));context.requireApproved();return new Verified(a,project,context,reference,field,value,provenance,codec.hash(manifest));
    }
    final class Verified {
        private final EnterpriseAccess.Admission a;private final String project;private final TaskStrictFieldContextService.Verified context;private final StrictFieldComparisonProtocol.SourceExactReference reference;private final SourceExactProtocol.Field field;private final ArtifactProtocol.FieldValue value;private final StrictFieldComparisonProtocol.Provenance provenance;private final String witness;
        private Verified(EnterpriseAccess.Admission a,String project,TaskStrictFieldContextService.Verified context,StrictFieldComparisonProtocol.SourceExactReference reference,SourceExactProtocol.Field field,ArtifactProtocol.FieldValue value,StrictFieldComparisonProtocol.Provenance provenance,String witness){this.a=a;this.project=project;this.context=context;this.reference=reference;this.field=field;this.value=value;this.provenance=provenance;this.witness=witness;}
        void requireUnchanged()throws Exception{var current=require(a,project,context,reference);if(!witness.equals(current.witness)||!field.equals(current.field))bad();}ArtifactProtocol.FieldValue value(){return value;}StrictFieldComparisonProtocol.Provenance provenance(){return provenance;}SourceExactProtocol.Field field(){return field;}
    }
    private static String str(Map<String,Object> r,String k){return Objects.requireNonNull(r.get(k)).toString();}private static <T>T one(List<T> r){if(r.size()!=1)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
